import {DB,mediaPut,mediaAll,mediaDelete,uid,download,player} from './data.js';
import {nameKeyboard} from './keyboard.js';
import {VOICE_EFFECTS,clamp} from './media-core.js';
import {processVoice,wavBlob,audioData,dataBlob} from './media-audio.js';
import {drawMonster,drawZooAnimal,mediaCoverArt} from './media-art.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const mediaName=(modal,{title,value,onSave})=>nameKeyboard(modal,{title,value,onSave});
export async function safeMediaPut(item,notify){try{await mediaPut(item);return true;}catch(e){notify('Could not save: device storage may be full. Your draft is still open; export it before leaving.','error');return false;}}
export function paintThumb(canvas,kind,data){const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);c.fillStyle='#263b4e';c.fillRect(0,0,canvas.width,canvas.height);if(kind==='monster')drawMonster(c,data,canvas.width/2,canvas.height*.65,canvas.height/360,{smile:.65});else drawZooAnimal(c,data,canvas.width/2,canvas.height*.58,canvas.height/240,{state:'idle'});}
export function openVoiceEditor({modal,session,notify,owner=DB.active,name='My funny voice',existing=null,onSave}){
 session.silence();const d=modal(`<div class="voice-editor"><span class="eyebrow">LOCAL SOUND LAB · YOUR VOICE, YOUR RULES</span><h2>${esc(name)}</h2><p>Make any silly sound you like. We never judge what an animal “should” sound like.</p><div class="voice-status"><strong data-voice-time>0.0s</strong><span data-voice-state>Ready to record.</span><meter data-voice-level min="0" max="1" value="0"></meter></div><canvas data-voice-wave width="900" height="130" aria-label="Voice waveform and trim selection"></canvas><div class="voice-buttons"><button class="btn primary" data-voice-record>● RECORD</button><button class="btn danger" data-voice-stop disabled>■ STOP</button><button class="btn secondary" data-voice-preview disabled>▶ PREVIEW</button><label class="btn secondary file-btn">IMPORT SOUND<input data-voice-import type="file" accept="audio/*" hidden></label></div><div class="voice-fields"><label>Recording limit<select data-voice-limit><option value="2">2 seconds</option><option value="3">3 seconds</option><option value="5" selected>5 seconds</option></select></label><label>Voice effect<select data-voice-effect>${VOICE_EFFECTS.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Playback volume<input data-voice-volume type="range" min="0" max="100" value="80"></label><label>Trim start<input data-voice-in type="range" min="0" max="5" step=".01" value="0"></label><label>Trim end<input data-voice-out type="range" min="0" max="5" step=".01" value="5"></label></div><p data-voice-message role="status">Recording starts after a short countdown. Keep your speaking voice comfortable.</p><div class="modal-actions"><button class="btn secondary" data-voice-cancel>CANCEL</button><button class="btn primary" data-voice-use disabled>USE THIS VOICE →</button><button class="btn secondary" data-voice-export disabled>EXPORT WAV</button></div></div>`);
 const q=s=>d.querySelector(s);let closed=false,raw=existing?.data||null,settings={effect:'Original',start:0,end:raw?.duration||0,volume:.8,...raw?.settings},countdown=null,poll=null,preview=null,recording=false,finishing=false;const hadMic=session.micActive;
 function message(text){if(!closed)q('[data-voice-message]').textContent=text;}
 function stopPreview(){try{preview?.stop();}catch{}preview=null;}
 function wave(){if(!raw||closed)return;const c=q('[data-voice-wave]'),x=c.getContext('2d'),a=raw.channels[0];x.fillStyle='#101d31';x.fillRect(0,0,c.width,c.height);x.fillStyle='#72d7c12b';x.fillRect(settings.start/raw.duration*c.width,0,(settings.end-settings.start)/raw.duration*c.width,c.height);x.strokeStyle='#7be7d1';x.beginPath();for(let i=0;i<c.width;i++){let peak=0;for(let j=Math.floor(i*a.length/c.width);j<Math.floor((i+1)*a.length/c.width);j++)peak=Math.max(peak,Math.abs(a[j]));x.moveTo(i,65-peak*60);x.lineTo(i,65+peak*60);}x.stroke();q('[data-voice-time]').textContent=(settings.end-settings.start).toFixed(2)+'s';}
 function ready(data,keep=false){raw=data;if(!keep){settings.start=0;settings.end=raw.duration;}for(const [selector,value]of [['[data-voice-in]',settings.start],['[data-voice-out]',settings.end]]){q(selector).max=raw.duration;q(selector).value=value;}for(const s of ['preview','use','export'])q('[data-voice-'+s+']').disabled=false;q('[data-voice-state]').textContent='Captured locally · preview, trim and keep it.';message(raw.quiet?'This recording is very quiet. Try moving the microphone closer, or rerecord in your normal voice.':'Your original recording stays intact when you change effects.');wave();}
 async function finish(){if(finishing||!recording)return;finishing=true;recording=false;try{const data=await session.stopVoice();if(!closed&&data)ready(data);}catch(e){message(e.message);}finally{finishing=false;if(!closed){q('[data-voice-stop]').disabled=true;q('[data-voice-record]').disabled=false;q('[data-voice-level]').value=0;}}}
 q('[data-voice-record]').onclick=()=>{if(recording||countdown)return;stopPreview();for(const action of ['preview','use','export'])q('[data-voice-'+action+']').disabled=true;clearInterval(poll);let n=3;q('[data-voice-state]').textContent='Get ready… '+n;q('[data-voice-record]').disabled=true;countdown=setInterval(async()=>{n--;if(closed)return;if(n){q('[data-voice-state]').textContent='Get ready… '+n;return;}clearInterval(countdown);countdown=null;try{const rec=await session.recordVoice(+q('[data-voice-limit]').value,(level,time)=>{if(closed)return;q('[data-voice-level]').value=level;q('[data-voice-time]').textContent=time.toFixed(1)+'s';});if(closed){await session.stopVoice();return;}if(!rec){q('[data-voice-record]').disabled=false;return;}recording=true;q('[data-voice-stop]').disabled=false;q('[data-voice-state]').textContent='● MICROPHONE RECORDING';poll=setInterval(()=>{if(['ready','idle'].includes(session.voiceRecorder?.state))finish();},100);}catch(e){message(e.message);q('[data-voice-record]').disabled=false;if(raw)ready(raw,true);}},700);};
 q('[data-voice-stop]').onclick=finish;q('[data-voice-cancel]').onclick=()=>d.close();q('[data-voice-preview]').onclick=async()=>{stopPreview();if(raw)preview=await session.play(await processVoice(raw,settings));};
 for(const [selector,key]of [['effect','effect'],['volume','volume'],['in','start'],['out','end']])q('[data-voice-'+selector+']').oninput=e=>{stopPreview();settings[key]=key==='effect'?e.target.value:key==='volume'?+e.target.value/100:+e.target.value;if(raw){settings.start=clamp(settings.start,0,Math.max(0,raw.duration-.02));settings.end=clamp(settings.end,settings.start+.01,raw.duration);}wave();};
 q('[data-voice-import]').onchange=async e=>{try{const file=e.target.files[0];if(!file||recording||countdown)return;const ac=await session.audio(),buffer=await ac.decodeAudioData(await file.arrayBuffer());if(buffer.duration>15)throw Error('Choose a sound under 15 seconds for a short animal or monster voice.');if(!closed)ready(audioData(buffer));}catch(e){message(e.message);}};
 q('[data-voice-export]').onclick=async()=>{if(raw)download(wavBlob(await processVoice(raw,settings)),'Little-Big-Arcade-voice.wav');};
 q('[data-voice-use]').onclick=async()=>{if(!raw||recording||countdown||finishing)return;q('[data-voice-use]').disabled=true;const item={id:uid(),type:'voice',owner,name,at:Date.now(),data:{...raw,settings:{...settings}}};try{if(!await safeMediaPut(item,notify)){q('[data-voice-use]').disabled=false;return;}await onSave(item);d.close();}catch(e){message(e.message);q('[data-voice-use]').disabled=false;}};
 d.addEventListener('close',()=>{closed=true;clearInterval(countdown);clearInterval(poll);stopPreview();session.stopVoice().catch(()=>{});if(!hadMic)session.stop('mic');},{once:true});if(raw){ready(raw,true);q('[data-voice-effect]').value=settings.effect;q('[data-voice-volume]').value=settings.volume*100;}return d;
}
export async function mediaGallery(container,{owner=DB.active,types=['capture','monster','voice'],modal,notify,ask,onOpen,onBack}){
 const all=(await mediaAll()).filter(x=>types.includes(x.type)&&x.owner===owner).sort((a,b)=>Number(!!b.favorite)-Number(!!a.favorite)||(b.at||0)-(a.at||0));container.innerHTML=`<div class="media-gallery"><header><div><span class="eyebrow">${esc(player(owner)?.name||'FAMILY')}’S LOCAL GALLERY</span><h2>Made by you.</h2><p>Saved on this device. Export an arcade backup to keep an extra copy.</p></div><button class="btn secondary" data-gallery-back>← BACK</button></header><div class="media-gallery-grid">${all.map(item=>`<article><div class="media-preview">${item.type==='capture'?item.data.kind==='photo'?`<img src="${item.data.src}" alt="${esc(item.name)}">`:`<video src="${item.data.src}" poster="${item.thumb||''}" controls playsinline preload="metadata"></video>`:item.type==='monster'?'<canvas width="400" height="230" data-character="'+item.id+'"></canvas>':'<div class="voice-gallery-symbol">LOCAL VOICE<br><b>'+item.data.duration.toFixed(1)+' seconds</b></div>'}</div><h3>${esc(item.name)}</h3><small>${item.type.toUpperCase()} · ${new Date(item.at).toLocaleDateString()}</small><div class="gallery-buttons"><button data-open="${item.id}" class="btn primary">${item.type==='voice'?'PLAY / EDIT':'OPEN / EDIT'}</button><button data-fav="${item.id}" class="btn secondary">${item.favorite?'★ FAVORITE':'☆ FAVORITE'}</button><button data-rename="${item.id}" class="btn secondary">RENAME</button><button data-copy="${item.id}" class="btn secondary">DUPLICATE</button><button data-export="${item.id}" class="btn secondary">EXPORT</button><button data-delete="${item.id}" class="btn secondary">DELETE</button></div></article>`).join('')||'<section class="panel"><h3>Your first creation belongs here.</h3><p>Capture a photo, save a monster or record a voice to start your collection.</p></section>'}</div><button class="btn secondary" data-clear-media>ADULT TOOLS · CLEAR MY MEDIA</button></div>`;
 container.querySelector('[data-gallery-back]').onclick=onBack;for(const item of all){const find=k=>container.querySelector(`[data-${k}="${item.id}"]`);if(item.type==='monster')paintThumb(container.querySelector(`[data-character="${item.id}"]`),'monster',item.data.design);find('open').onclick=()=>onOpen(item);find('fav').onclick=async()=>{await mediaPut({...item,favorite:!item.favorite});await mediaGallery(container,{owner,types,modal,notify,ask,onOpen,onBack});};find('rename').onclick=()=>mediaName(modal,{title:'Name your creation',value:item.name,onSave:async name=>{await mediaPut({...item,name});await mediaGallery(container,{owner,types,modal,notify,ask,onOpen,onBack});}});find('copy').onclick=async()=>{await safeMediaPut({...structuredClone(item),id:uid(),name:(item.name+' copy').slice(0,60),at:Date.now()},notify);await mediaGallery(container,{owner,types,modal,notify,ask,onOpen,onBack});};find('delete').onclick=async()=>{if(await ask('Delete '+item.name+'?','This removes this saved item from this device. Other saved media and profiles remain.')){await mediaDelete(item.id);await mediaGallery(container,{owner,types,modal,notify,ask,onOpen,onBack});}};find('export').onclick=async()=>{if(item.type==='capture')download(dataBlob(item.data.src),item.name+(item.data.kind==='photo'?'.png':item.data.mime.includes('mp4')?'.mp4':'.webm'));else if(item.type==='voice')download(wavBlob(await processVoice(item.data,item.data.settings)),item.name+'.wav');else download(new Blob([JSON.stringify(item)],{type:'application/json'}),item.name+'.json');};}
 container.querySelector('[data-clear-media]').onclick=async()=>{if(await ask('Adult tools: clear saved media for '+player(owner).name+'?','Photos, videos, voices and monsters belonging to this profile will be removed. Zoo animals keep their names and upgrades, but deleted voices will need rerecording. Existing games, scores and other profiles stay intact.')){for(const item of all)await mediaDelete(item.id);await mediaGallery(container,{owner,types,modal,notify,ask,onOpen,onBack});}};
}
export function mediaRecords(container,{game,onBack}){let difficulty=3,players='solo',activity=game==='zoo'?'sound-guessing':game==='funny'?'poses':'expression';const activities=game==='zoo'?['sound-guessing','choir-battle']:game==='funny'?['poses','booth']:['expression','mimic','voice','faceoff'];function render(){const rows=DB.profiles.map(p=>({p,r:p.results.filter(r=>r.game===game&&r.ruleset==='media-v1'&&r.difficulty===difficulty&&r.mode===players&&r.levelId===activity).sort((a,b)=>b.score-a.score||a.duration-b.duration)[0]})).filter(x=>x.r).sort((a,b)=>b.r.score-a.r.score||a.r.duration-b.r.duration);container.innerHTML=`<div class="media-records"><header><div><span class="eyebrow">REAL INPUT · SAVED LOCAL RESULTS</span><h2>Challenge records.</h2><p>Creative media has no competitive score. Activities, difficulties and player modes stay separate.</p></div><button class="btn primary" data-media-record-back>← BACK</button></header><div class="media-record-filters"><label>Activity<select data-record-activity>${activities.map(a=>`<option ${activity===a?'selected':''}>${a}</option>`).join('')}</select></label><label>Difficulty<select data-record-difficulty>${['Easy','Normal','Hard','Very Hard','Expert'].map((d,i)=>`<option value="${i+1}" ${difficulty===i+1?'selected':''}>${d}</option>`).join('')}</select></label><label>Players<select data-record-players><option value="solo" ${players==='solo'?'selected':''}>One player</option><option value="versus" ${players==='versus'?'selected':''}>Two players</option></select></label></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>RANK</th><th>PLAYER</th><th>POINTS</th><th>CORRECT</th><th>ACCURACY</th><th>ACTIVE TIME</th></tr></thead><tbody>${rows.map(({p,r},i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${r.score}</td><td>${r.hits}</td><td>${r.accuracy}%</td><td>${r.duration.toFixed(1)}s</td></tr>`).join('')}</tbody></table></div>`:'<section class="panel"><h3>Your next record belongs here.</h3><p>Finish this exact activity to add a result.</p></section>'}</div>`;container.querySelector('[data-media-record-back]').onclick=onBack;container.querySelector('[data-record-activity]').onchange=e=>{activity=e.target.value;render();};container.querySelector('[data-record-difficulty]').onchange=e=>{difficulty=+e.target.value;render();};container.querySelector('[data-record-players]').onchange=e=>{players=e.target.value;render();};}render();}
